-- Bring the hosted catalogue in line with local.
--
-- GENERATED by prisma/generate-catalogue-sync.js on 2026-10-09.
-- Don't hand-edit this file — change the local database and re-run the
-- generator, so local stays the single source of truth.
--
--   mysql -u USER -p --default-character-set=utf8mb4 DBNAME < sync-catalogue-to-live.sql
--
-- The --default-character-set=utf8mb4 is required, or the accented
-- characters in the descriptions are mangled on import.
--
-- Rows are matched on each table's own unique key (excursions.slug,
-- rental_items.slug, rental_spots(item, code), rental_time_slots(item, label))
-- and never on id, so a row that already exists on the host is updated in
-- place and keeps the id its existing bookings point at. The location is
-- resolved at run time, because the hosted location id differs from local.
--
-- Nothing here deletes a catalogue item: one that exists on the host but
-- not locally is left in place rather than dropped, because it may have
-- bookings against it. Retire those from the admin panel instead.
--
-- Departure times are the one exception — they are replaced per excursion,
-- which is safe because bookings reference the excursion, not the
-- departure_times row. Rental spots and time slots that exist on the host
-- but not locally are deactivated rather than deleted, so they stop being
-- bookable without breaking the bookings already attached to them.
--
-- Bookings, orders, locations, settings and admin users are untouched.

SET NAMES utf8mb4;

START TRANSACTION;

-- The host's location row (local 'coccolobo-main' vs live 'carambola-main'),
-- resolved by age rather than by a hardcoded id.
SET @loc = (SELECT id FROM locations ORDER BY createdAt LIMIT 1);

