-- ===================== Verify =====================
SELECT slug, title, durationMinutes, cutoffTime, minGuests, pricingType, status FROM excursions ORDER BY slug;
SELECT slug, name, durationMinutes, priceAdult, status FROM rental_items ORDER BY slug;
SELECT 'leftover WiFi / persons / Cocolobo' AS check_name,
  (SELECT COUNT(*) FROM excursions WHERE CONCAT_WS(' ', description, included, excluded) REGEXP 'WiFi|persons|Cocolobo Beach')
  + (SELECT COUNT(*) FROM rental_items WHERE description REGEXP 'WiFi|persons|Cocolobo Beach') AS should_be_zero;

